using System.IO.Compression;
using System.Text.Json;
using Nutrition.Api.Domain;

namespace Nutrition.Api.Services.FoodLookup;

/// <summary>
/// Packaged products from the Open Food Facts export for the countries whose shelves the account
/// shops from (Malaysia and Singapore, and their common imports), generated by tools/off-import and
/// embedded in the API. Each row was read from the full product record, so its per-100 basis, measure
/// and serving are already known and search never waits on the live service.
/// </summary>
public sealed class OpenFoodFactsDataset
{
    public const string ResourceName="off-products.json.gz";

    private OpenFoodFactsDataset(IReadOnlyList<BundledFood> entries,string? exported)
    {
        Entries=entries;
        Exported=exported;
    }

    public IReadOnlyList<BundledFood> Entries { get; }
    /// <summary>The date of the export the generator read, recorded with the data.</summary>
    public string? Exported { get; }
    public int Count=>Entries.Count;

    /// <summary>The dataset compiled into this assembly, or null when a build left it out.</summary>
    public static OpenFoodFactsDataset? Embedded()
    {
        using var stream=typeof(OpenFoodFactsDataset).Assembly.GetManifestResourceStream(ResourceName);
        return stream is null?null:Load(stream);
    }

    public static OpenFoodFactsDataset Load(Stream gzip)
    {
        using var inflated=new GZipStream(gzip,CompressionMode.Decompress);
        using var json=JsonDocument.Parse(inflated);
        var entries=new List<BundledFood>();
        foreach(var food in json.RootElement.GetProperty("foods").EnumerateArray())
            if(Read(food) is { } entry)entries.Add(entry);
        return new OpenFoodFactsDataset(entries,FoodResults.Text(json.RootElement,"exported"));
    }

    private static BundledFood? Read(JsonElement food)
    {
        var name=FoodResults.Text(food,"n");
        var code=FoodResults.Text(food,"code");
        if(name is null||code is null||FoodResults.Number(food,"k") is not { } calories)return null;
        var measure=FoodResults.Text(food,"m")==Measures.Millilitres?Measures.Millilitres:Measures.Grams;
        var portions=new List<FoodPortion>();
        if(food.TryGetProperty("s",out var servings)&&servings.ValueKind==JsonValueKind.Array)
            foreach(var serving in servings.EnumerateArray())
                if(serving.ValueKind==JsonValueKind.Array&&serving.GetArrayLength()==2&&serving[0].GetString() is { } label&&FoodResults.TryNumber(serving[1],out var amount))
                    portions.Add(new FoodPortion(label,amount));
        var limited=FoodResults.LimitPortions(portions);
        var result=new FoodResult(FoodResults.Label(name,FoodResults.Text(food,"b")),calories,
            FoodResults.Number(food,"p"),FoodResults.Number(food,"f"),FoodResults.Number(food,"c"),FoodResults.Number(food,"fi"),
            OpenFoodFactsParser.Attribution+" / "+code,100,limited,code,FoodResults.ServingCalories(calories,limited),"per100g",measure);
        // The label is "Name · Brand" when the brand is not already in the name; the name leads.
        return new BundledFood(result,FoodRanking.Stems(result.Name),FoodRanking.Stems(name).Length);
    }
}
